const body = ($input.first().json && $input.first().json.body) || $input.first().json || {};
const apiBase = ($env.GITHUB_API_BASE || 'https://github.boschdevcloud.com/api/v3').replace(/\/$/, '');
const f2e = ($env.EDIFACT_API_BASE || 'http://host.docker.internal:8000').replace(/\/$/, '');
const owner = 'RSR1DY';
const repo = 'masterdata';
const branch = body.branch || $env.MASTERDATA_REPO_BRANCH || 'main';
const files = [
  { kind: 'customers', parquet: '10564_Customers.parquet', csv: '10564_Customers.csv' },
  { kind: 'partners', parquet: '10564_Partners.parquet', csv: '10564_Partners.csv' },
  { kind: 'materials', parquet: 'DB_Materials.parquet', csv: 'DB_Materials.csv' },
  { kind: 'salesorders', parquet: 'DB_Salesorder.parquet', csv: 'DB_Salesorder.csv' },
];
return files.map((f) => ({
  json: {
    reason: body.reason || 'manual_ui',
    actor: body.actor || 'n8n',
    kind: f.kind,
    parquet: f.parquet,
    csv: f.csv,
    file: f.parquet,
    format: 'parquet',
    branch,
    metaUrl: `${apiBase}/repos/${owner}/${repo}/contents/${f.parquet}?ref=${encodeURIComponent(branch)}`,
    metaUrlCsv: `${apiBase}/repos/${owner}/${repo}/contents/${f.csv}?ref=${encodeURIComponent(branch)}`,
    importUrl: `${f2e}/api/masterdata/import`,
  },
}));

const listed = $('1. Lister fichiers').all();
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const meta = (listed[i] && listed[i].json) || {};
  const j = $input.all()[i].json || {};
  const status = Number(j.statusCode || j.status || 0);
  const downloadUrl = j.download_url || '';
  const size = Number(j.size || 0);
  const okParquet = (status === 0 || (status >= 200 && status < 300)) && size > 0 && downloadUrl;
  if (okParquet) {
    out.push({
      json: {
        kind: meta.kind,
        file: meta.parquet,
        format: 'parquet',
        importUrl: meta.importUrl,
        reason: meta.reason,
        actor: meta.actor,
        download_url: downloadUrl,
        size,
        skip: false,
      },
    });
    continue;
  }
  out.push({
    json: {
      kind: meta.kind,
      file: meta.csv,
      format: 'csv',
      importUrl: meta.importUrl,
      reason: meta.reason,
      actor: meta.actor,
      metaUrl: meta.metaUrlCsv,
      parquetError: j.message || j.error || `meta parquet HTTP ${status || 'fail'}`,
      needCsvMeta: true,
      skip: false,
    },
  });
}
return out;

const item = $input.first();
const gh = item.json || {};
let prev = {};
try {
  const p = item.pairedItem;
  const idx = typeof p === 'object' ? p.item : (p ?? 0);
  prev = $('3. Choisir source').itemMatching(idx).json || {};
} catch (e) {
  prev = gh;
}
const status = Number(gh.statusCode || gh.status || 0);
const downloadUrl = gh.download_url || '';
const size = Number(gh.size || 0);
const okMeta = (status === 0 || (status >= 200 && status < 300)) && size > 0 && downloadUrl;
if (!okMeta) {
  return [{ json: { kind: prev.kind, file: prev.csv, importUrl: prev.importUrl, skip: true, ok: false, message: `GitHub introuvable: ${prev.parquet} / ${prev.csv}` } }];
}
return [{ json: { kind: prev.kind, file: prev.csv, format: 'csv', importUrl: prev.importUrl, reason: prev.reason, actor: prev.actor, download_url: downloadUrl, size, skip: false } }];

const item = $input.first();
let prev = item.json || {};
if (!prev.kind || !prev.file) {
  try {
    const p = item.pairedItem;
    const idx = typeof p === 'object' ? p.item : (p ?? 0);
    prev = $('3. Choisir source').itemMatching(idx).json || prev;
  } catch (e) {
    try {
      const p = item.pairedItem;
      const idx = typeof p === 'object' ? p.item : (p ?? 0);
      prev = $('6. Prep CSV').itemMatching(idx).json || prev;
    } catch (e2) {}
  }
}
const bin = item.binary && item.binary.data;
let bytes = 0;
if (bin && bin.data) {
  try { bytes = Buffer.from(bin.data, bin.encoding || 'base64').length; } catch (e) { bytes = Number(bin.fileSize || 0); }
}
const effective = Math.max(bytes, Number(bin && bin.fileSize || 0), Number(prev.size || 0));
if (!bin || effective <= 0) {
  return [{ json: { kind: prev.kind, file: prev.file, importUrl: prev.importUrl, skip: true, ok: false, message: `Download vide: ${prev.file || prev.kind}` } }];
}
return [{
  json: {
    kind: prev.kind,
    file: prev.file,
    format: prev.format || 'parquet',
    importUrl: prev.importUrl,
    reason: prev.reason,
    actor: prev.actor,
    size: effective,
    skip: false,
  },
  binary: {
    data: {
      ...bin,
      fileName: prev.file || bin.fileName || 'data.bin',
      mimeType: (prev.format === 'csv') ? 'text/csv' : 'application/octet-stream',
    },
  },
}];

const listed = $('1. Lister fichiers').all();
const prepByKind = {};
try {
  for (const it of $('9. Valider blob').all()) {
    if (it.json && it.json.kind) prepByKind[it.json.kind] = it.json;
  }
} catch (e7) {}
try {
  for (const it of $('6. Prep CSV').all()) {
    if (it.json && it.json.kind) prepByKind[it.json.kind] = it.json;
  }
} catch (e) {}
try {
  for (const it of $('11. Skip import ?').all()) {
    if (it.json && it.json.kind && it.json.skip) prepByKind[it.json.kind] = it.json;
  }
} catch (e6) {}
const imports = $('12. File2EDI import').all();
const files = [];
let synced = 0;
let failed = 0;
let impIdx = 0;

for (let i = 0; i < listed.length; i++) {
  const meta = (listed[i] && listed[i].json) || {};
  const kind = meta.kind;
  const prep = prepByKind[kind] || {};
  const fileName = prep.file || meta.parquet || meta.csv || kind || `item-${i}`;

  if (prep.skip) {
    failed += 1;
    files.push({ file: fileName, kind, ok: false, message: String(prep.message || 'skip') });
    continue;
  }

  const j = (imports[impIdx] && imports[impIdx].json) || {};
  impIdx += 1;
  const status = Number(j.statusCode || j.status || 0);
  const ok = j.ok === true || (status > 0 && status < 400);
  if (ok) {
    synced += 1;
    files.push({ file: fileName, kind, ok: true, rows: j.rows, format: prep.format || j.format, message: j.message || 'OK' });
  } else {
    failed += 1;
    files.push({ file: fileName, kind, ok: false, message: String(j.message || j.detail || j.error || `HTTP ${status || 'fail'}`) });
  }
}

const total = listed.length;
const okNames = files.filter((f) => f.ok).map((f) => f.file).join(', ');
const koNames = files.filter((f) => !f.ok).map((f) => `${f.file}: ${f.message}`).join(' | ');
return [{
  json: {
    ok: failed === 0 && synced > 0,
    synced,
    failed,
    expected: total,
    files,
    source: 'n8n-github',
    repo: 'https://github.boschdevcloud.com/RSR1DY/masterdata.git',
    message: failed === 0
      ? `Sync masterdata OK — ${synced}/${total}: ${okNames}`
      : `Sync masterdata partielle — ${synced}/${total} OK (${okNames || 'aucun'}), ${failed} echec(s) (${koNames})`,
  },
}];

try {
  if (($('8. Download').all() || []).length > 0) return [];
} catch (e) {}
try {
  if (($('12. File2EDI import').all() || []).length > 0) return [];
} catch (e2) {}
const listed = $('1. Lister fichiers').all();
const prepByKind = {};
try {
  for (const it of $('9. Valider blob').all()) {
    if (it.json && it.json.kind) prepByKind[it.json.kind] = it.json;
  }
} catch (e3) {}
try {
  for (const it of $('6. Prep CSV').all()) {
    if (it.json && it.json.kind) prepByKind[it.json.kind] = it.json;
  }
} catch (e4) {}
try {
  for (const it of $('11. Skip import ?').all()) {
    if (it.json && it.json.kind && it.json.skip) prepByKind[it.json.kind] = it.json;
  }
} catch (e5) {}
let pending = 0;
for (const item of listed) {
  const kind = (item.json && item.json.kind) || '';
  if (!kind || !prepByKind[kind]) pending += 1;
}
if (pending > 0) return [];
const nonSkip = Object.values(prepByKind).filter((p) => p && !p.skip);
if (nonSkip.length > 0) return [];
const files = [];
let failed = 0;
for (let i = 0; i < listed.length; i++) {
  const meta = (listed[i] && listed[i].json) || {};
  const kind = meta.kind;
  const prep = prepByKind[kind] || {};
  const fileName = prep.file || meta.parquet || meta.csv || kind || `item-${i}`;
  failed += 1;
  files.push({ file: fileName, kind, ok: false, message: String(prep.message || 'skip') });
}
const total = listed.length;
const koNames = files.map((f) => `${f.file}: ${f.message}`).join(' | ');
return [{
  json: {
    ok: false,
    synced: 0,
    failed,
    expected: total,
    files,
    source: 'n8n-github',
    repo: 'https://github.boschdevcloud.com/RSR1DY/masterdata.git',
    message: `Sync masterdata partielle — 0/${total} OK (aucun), ${failed} echec(s) (${koNames})`,
  },
}];

let agg = {};
try { agg = $('13. Aggregator').first().json || {}; } catch (e) {}
if (!agg.message) {
  try { agg = $('13b. Skip-only agg').first().json || agg; } catch (e2) {}
}
const reload = $input.first().json || {};
const reloadOk = reload.status === 'ok' || Number(reload.statusCode || 0) === 200 || !reload.error;
return [{ json: { ...agg, cache_reloaded: !!reloadOk, message: (agg.message || 'Sync') + (reloadOk ? ' — cache recharge' : ' — reload-cache echec') } }];
